    throw new BumpError(`current version '${current}' is not <major>.<ymmdd>.<n> (e.g. 1.61231.3)`);
  }
  const [, major, curDay, n] = m;
  const today = ymmdd(now);

  if (today === curDay) return `${major}.${today}.${Number(n) + 1}`;
  if (Number(today) > Number(curDay)) return `${major}.${today}.1`;

  // A decrease. The decade wrap (…9xxxx -> …0xxxx) is the one legitimate one,
  // and the major exists to absorb it.
  if (curDay[0] === '9' && today[0] === '0') return `${Number(major) + 1}.${today}.1`;

  throw new BumpError(
    `current version '${current}' is dated ${curDay}, ahead of today (${today}) — refusing to bump. ` +
    'A version from the future means a hand edit or a wrong clock, not a decade wrap.'
  );
}

===ACTION===
name: Bump the site version
description: >-
  Raises the site's DATE-ANCHORED version — <major>.<ymmdd>.<n> — across every
  file the repo declares as a version record (its `version_files` config), and
  outputs the new version. The scheme and its rules (the year digit, the day
  counter, the decade wrap) live in bump.mjs beside this file; the pipeline
  passes only the paths, so no repo carries a bump script of its own. Composite
  so it adds no reusable-workflow nesting level, and dependency-free so it runs
  on a bare runner.

inputs:
  version_files:
    description: >-
      Space-separated version-record paths (the repo's `version_files`). The
      first is the source of truth; the rest must already agree with it.
    required: true

outputs:
  version:
    description: The new <major>.<ymmdd>.<n> version
    value: ${{ steps.bump.outputs.version }}

runs:
  using: composite
  steps:
    - id: bump
      shell: bash
      run: node "${{ github.action_path }}/bump.mjs" ${{ inputs.version_files }}

