    '.github/workflows/static-site-ci.yml': 'name: CI\non:\n  pull_request:\nrun: node .github/actions/read-site-config/export-build-vars.mjs\n',
  });
  try {
    assert.deepEqual(run(releaseWorkflows, root), []);
  } finally { cleanup(root); }
});

