      ? readVersion(files[0], readFileSync(files[0], 'utf8'))
      : bump(files, part);
    if (process.env.GITHUB_OUTPUT) appendFileSync(process.env.GITHUB_OUTPUT, `version=${version}\n`);
    console.log(version);
  } catch (err) {
    console.error(`bump-extension-version: ${err.message}`);
    process.exit(1);
  }
}

